#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=9

# Everything private stays in one file only you can read; nothing here prints a value.
ENV_FILE="${ENV_FILE:-$HOME/.config/gitaway/wallet.env}"
mkdir -p "$(dirname "$ENV_FILE")"
WORK="$(umask 077 && mktemp -d)"
trap 'rm -rf "$WORK"' EXIT
command -v openssl >/dev/null 2>&1 || { echo "openssl is needed"; exit 1; }

banner "GitAway: Apple Wallet and Google Wallet passes (F-288)"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Apple: your Team ID"
say "Apple needs your Developer Program membership (99 USD a year). Already a member? Good."
open_url "https://developer.apple.com/account#MembershipDetailsCard"
step "Under Membership details, copy the Team ID (10 letters and digits)."
ask APPLE_TEAM_ID "Team ID:"
write_env APPLE_TEAM_ID "$APPLE_TEAM_ID"

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Apple: the Pass Type ID"
open_url "https://developer.apple.com/account/resources/identifiers/list/passTypeId"
step "Press the blue + (Register a new identifier), choose Pass Type IDs, Continue."
step "Description: GitAway stay. Identifier: pass.me.gitaway.stay (it must start with pass.). Continue, Register."
ask APPLE_PASS_TYPE_ID "The identifier you registered (pass....):"
write_env APPLE_PASS_TYPE_ID "$APPLE_PASS_TYPE_ID"

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Apple: make the key and ask Apple for the certificate"
say "This makes the private key here, on your machine. It leaves it only as the Railway variable at the end."
openssl req -new -newkey rsa:2048 -nodes -keyout "$WORK/pass-key.pem" -out "$WORK/pass.csr" -subj "/CN=GitAway pass/O=GitAway" >/dev/null 2>&1
CSR_OUT="$HOME/Downloads/gitaway-pass.csr"
[[ -d "$HOME/Downloads" ]] || CSR_OUT="$PWD/gitaway-pass.csr"
cp "$WORK/pass.csr" "$CSR_OUT"
say "A certificate request was saved as $CSR_OUT"
open_url "https://developer.apple.com/account/resources/identifiers/list/passTypeId"
step "Open your Pass Type ID, press Create Certificate (under Production), Continue."
step "Upload gitaway-pass.csr, Continue, then Download. You get pass.cer."
ask CER_PATH "Where is the downloaded pass.cer? (drag the file here)"
CER_PATH="${CER_PATH//\'/}"
openssl x509 -inform DER -in "$CER_PATH" -out "$WORK/cert.pem" 2>/dev/null || openssl x509 -in "$CER_PATH" -out "$WORK/cert.pem"
openssl x509 -in "$WORK/cert.pem" -noout -subject | grep -q "$APPLE_PASS_TYPE_ID" || warn "the certificate does not name $APPLE_PASS_TYPE_ID: is it for another Pass Type ID?"
note "the certificate is read"

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Apple: the WWDR intermediate certificate"
open_url "https://www.apple.com/certificateauthority/"
step "Under Apple Intermediate Certificates, download Worldwide Developer Relations - G4 (WWDR G4)."
ask WWDR_PATH "Where is the downloaded .cer? (drag the file here)"
WWDR_PATH="${WWDR_PATH//\'/}"
openssl x509 -inform DER -in "$WWDR_PATH" -out "$WORK/wwdr.pem" 2>/dev/null || openssl x509 -in "$WWDR_PATH" -out "$WORK/wwdr.pem"
if openssl verify -CAfile "$WORK/wwdr.pem" "$WORK/cert.pem" >/dev/null 2>&1; then
  say "Your pass certificate chains to this WWDR certificate."
else
  warn "this WWDR certificate did not verify your pass certificate. Another one on the same Apple page (G3 or G6) may be the one; run this wizard again, it remembers your answers."
  confirm "Keep going anyway?" || exit 1
fi
write_env APPLE_PASS_CERT_PEM_B64 "$(base64 -w0 "$WORK/cert.pem")"
write_env APPLE_PASS_KEY_PEM_B64 "$(base64 -w0 "$WORK/pass-key.pem")"
write_env APPLE_WWDR_PEM_B64 "$(base64 -w0 "$WORK/wwdr.pem")"
note "the key has no password, so APPLE_PASS_KEY_PASSWORD is not needed"

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Google: the Wallet issuer account"
open_url "https://pay.google.com/business/console"
step "Sign in and create the business profile if asked (name GitAway)."
step "Open Google Wallet API. Accept the terms. Copy the Issuer ID (a long number) from the top of that page."
ask GOOGLE_WALLET_ISSUER_ID "Issuer ID:"
write_env GOOGLE_WALLET_ISSUER_ID "$GOOGLE_WALLET_ISSUER_ID"

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Google: turn on the Wallet API and make the service account"
open_url "https://console.cloud.google.com/apis/library/walletobjects.googleapis.com"
step "Pick (or create) a Google Cloud project and press Enable on Google Wallet API."
open_url "https://console.cloud.google.com/iam-admin/serviceaccounts"
step "Create service account: name gitaway-wallet. Skip the optional role and user steps, Done."
step "Open it, Keys tab, Add key, Create new key, JSON, Create. A .json file downloads."
ask SA_PATH "Where is the downloaded .json? (drag the file here)"
SA_PATH="${SA_PATH//\'/}"
SA_EMAIL="$(sed -n 's/.*"client_email": *"\([^"]*\)".*/\1/p' "$SA_PATH" | head -n1)"
[[ -n "$SA_EMAIL" ]] || { warn "that file has no client_email: is it the service account key?"; exit 1; }
write_env GOOGLE_WALLET_SA_JSON_B64 "$(base64 -w0 "$SA_PATH")"
say "The service account is: $SA_EMAIL"
warn "Delete the downloaded .json from your Downloads now: the key lives in $ENV_FILE and, after stage 9, on Railway."

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Google: let the service account use your issuer"
open_url "https://pay.google.com/business/console"
step "Open Users (left menu), Invite a user."
step "Paste the service account email shown in the last stage. Access level: Developer. Invite."
say "Until Google approves publishing, only test accounts can save a pass:"
step "Google Wallet API, Manage, Test accounts: add the Google account on your phone."
note "To open it to everyone, request publishing access on the same Manage page (Google reviews the generic class). Apple has no such step."
pause "Done?"

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Check what is saved (names only)"
for k in APPLE_PASS_TYPE_ID APPLE_TEAM_ID APPLE_PASS_CERT_PEM_B64 APPLE_PASS_KEY_PEM_B64 APPLE_WWDR_PEM_B64 GOOGLE_WALLET_ISSUER_ID GOOGLE_WALLET_SA_JSON_B64; do
  if [[ -n "$(_existing "$k" || true)" ]]; then say "set: $k"; else warn "missing: $k"; fi
done

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "Railway: put the names on the web service (no deploy)"
say "Each value is read from $ENV_FILE and piped to Railway; none is printed. --skip-deploys: nothing restarts until you deploy."
if confirm "Set the seven variables on Railway's web service now?"; then
  RW="${RAILWAY:-railway}"
  "$RW" status | grep -q "Project: *gitaway" || { warn "railway is not linked to the gitaway project; run 'railway status'"; exit 1; }
  for k in APPLE_PASS_TYPE_ID APPLE_TEAM_ID APPLE_PASS_CERT_PEM_B64 APPLE_PASS_KEY_PEM_B64 APPLE_WWDR_PEM_B64 GOOGLE_WALLET_ISSUER_ID GOOGLE_WALLET_SA_JSON_B64; do
    v="$(_existing "$k" || true)"
    [[ -n "$v" ]] || { warn "skipping $k: not saved"; continue; }
    printf '%s' "$v" | "$RW" variables --service web --set-from-stdin "$k" --skip-deploys >/dev/null && say "set on Railway: $k"
  done
  unset v
  say "Deploy when you are ready: railway up --service web --detach (after railway status shows Project: gitaway)."
else
  SKIPPED+=("Railway variables: run this wizard again, or set the seven names from $ENV_FILE")
fi

finish
}

run_wizard "$@"; exit
